// // // // // // // // // // // // // // // // //   return { u, w };
// // // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // // RING_POINTS points spread evenly along a closed loop
// // // // // // // // // // // // // // // // // function resample(loop, n) {
// // // // // // // // // // // // // // // // //   const len = [0];
