// // // // // // // // // // // // // // // //   return [
// // // // // // // // // // // // // // // //     center.clone(),
// // // // // // // // // // // // // // // //     ringPointAt(ring, center, u, w, a0),
// // // // // // // // // // // // // // // //     ...arc.map((x) => x.p),
// // // // // // // // // // // // // // // //     ringPointAt(ring, center, u, w, a1),
// // // // // // // // // // // // // // // //   ];
// // // // // // // // // // // // // // // // }

// // // // // // // // // // // // // // // // // last resort: a circle at the crown's root end, a bit narrower than the crown
