// // // // // // // // // // // // // // //     // mesial + distal root (the split line runs cheek to tongue)
// // // // // // // // // // // // // // //     return [
// // // // // // // // // // // // // // //       { from: 0, to: 180, lenScale: 1 },
// // // // // // // // // // // // // // //       { from: 180, to: 360, lenScale: 0.95 },
