// // // // // // // // // // // // // // //   if (jaw === "upper" && type === 4) {
// // // // // // // // // // // // // // //     // upper first premolar: cheek-side + palatal root
// // // // // // // // // // // // // // //     return [
// // // // // // // // // // // // // // //       { from: 270, to: 450, lenScale: 1 },
