// // // // // // // // // // // // // let lastBuildInfo = ""; // how the last root was made (for the console line)

// // // // // // // // // // // // // // ---------- one root ----------

// // // // // // // // // // // // // // crownGeo: tooth geometry (indexed), apicalDir: unit vector pointing from the crown toward the root
