// // // // // // // // // // // //     const d = p.clone().sub(center);
// // // // // // // // // // // //     const rel = wrap(Math.atan2(d.dot(w), d.dot(u)) - a0);
// // // // // // // // // // // //     if (rel > 1e-6 && rel < span - 1e-6) arc.push({ rel, p });
// // // // // // // // // // // //   });
